/* @autogenerated */
import { Component, signal } from '@angular/core';
import { TestBed } from '@angular/core/testing';
import { MatDialog } from '@angular/material/dialog';
import { TranslocoTestingModule } from '@jsverse/transloco';
import { Observable, of } from 'rxjs';
import { Acl } from '@shared/data/acl/acl.model';
import { LongTask } from '@shared/data/long-task.model';
import { LongTaskService } from '../long-task-view/long-task.service';
import { BulkEditDialogData } from '../bulk-edit/bulk-edit-dialog.component';
import { BulkEditChange, BulkEditField } from '../bulk-edit/bulk-edit.model';
import { BaseBulkEditAction } from './base-bulk-edit-action';

interface Item {
  uid: string;
  name: string;
  address?: string;
}

const generic = signal<{ generic: Acl } | undefined>({ generic: { allows: [{ name: 'update', allowed: true }] } });
const repository = {
  acl: () => Object.assign(generic, { fetch: jasmine.createSpy('fetch') }) as any,
  checkAcl: jasmine.createSpy('checkAcl'),
  update: jasmine.createSpy('update'),
  displayProvider: () => ({ display: (item: Item) => item.name }),
};

@Component({ selector: 'test-bulk-edit-action', template: '' })
class TestBulkEditAction extends BaseBulkEditAction<Item> {
  readonly name = 'bulkEdit';
  protected readonly scope = 'test';
  protected readonly repository = repository;

  protected bulkFields(): readonly BulkEditField<Item>[] {
    return [
      { name: 'name', label: 'Name', type: 'text' },
      { name: 'address', label: 'Address', type: 'text', optional: true },
    ];
  }

  protected override toDialogData(count: number): BulkEditDialogData<Item> {
    return {
      title: 'Edit',
      count,
      singular: 'item',
      plural: 'items',
      confirm: 'Ok',
      cancel: 'No',
      fields: this.bulkFields(),
    };
  }
}

describe('BaseBulkEditAction', () => {
  let task: LongTask | undefined;

  const run = (changes: BulkEditChange[], items: Item[]) => {
    TestBed.inject(MatDialog).open = jasmine
      .createSpy('open')
      .and.returnValue({ afterClosed: () => of(changes) }) as any;
    const fixture = TestBed.createComponent(TestBulkEditAction);
    fixture.detectChanges();
    const action = fixture.componentInstance;
    action.selection = signal(items);
    action.run();
  };

  beforeEach(() => {
    task = undefined;
    repository.checkAcl.calls.reset();
    repository.update.calls.reset();
    repository.update.and.callFake((item: Item) => of(item));
    TestBed.configureTestingModule({
      imports: [
        TestBulkEditAction,
        TranslocoTestingModule.forRoot({
          langs: { 'test/en': { action: { 'bulk-edit': { fixedFields: 'Fixed:', notAllowed: 'Not allowed' } } } },
          translocoConfig: { availableLangs: ['en'], defaultLang: 'en' },
        }),
      ],
      providers: [
        { provide: MatDialog, useValue: {} },
        {
          provide: LongTaskService,
          useValue: {
            run: (_title: string, progress: Observable<LongTask>) => {
              progress.subscribe((step) => (task = step));
              return of(undefined);
            },
          },
        },
      ],
    });
  });

  afterEach(() => TestBed.resetTestingModule());

  it('skips the records where a field to change is fixed and updates the rest', () => {
    repository.checkAcl.and.callFake((key: string) =>
      of<Acl>(key === 'b' ? { fields: { noEditables: ['address'] } } : { fields: { noEditables: [] } }),
    );

    run(
      [{ field: 'address', operation: 'replace', value: 'Main St' }],
      [
        { uid: 'a', name: 'A' },
        { uid: 'b', name: 'B' },
      ],
    );

    expect(repository.update).toHaveBeenCalledTimes(1);
    expect(repository.update.calls.mostRecent().args[0]).toEqual({ uid: 'a', name: 'A', address: 'Main St' });
    const step = task!.steps[0];
    expect(step.oks).toEqual(['a']);
    expect(step.errors.length).toBe(1);
    expect(step.errors[0].item).toBe('b');
    expect(step.errors[0].fails[0].code).toBe('fixed-fields');
    expect(step.errors[0].fails[0].violation).toContain('Address');
  });

  it('does not touch a record that cannot be modified', () => {
    repository.checkAcl.and.returnValue(of<Acl>({ allows: [{ name: 'update', allowed: false }] }));

    run([{ field: 'name', operation: 'replace', value: 'X' }], [{ uid: 'a', name: 'A' }]);

    expect(repository.update).not.toHaveBeenCalled();
    expect(task!.steps[0].errors[0].fails[0].code).toBe('not-allowed');
  });
});
